import {createSlice, PayloadAction} from '@reduxjs/toolkit';
export const myTablesSlice = createSlice({
    name:'myTables',
    initialState:[] as {tableId:number, tableName:string, invoiceCode:string, data: {key: string,
        name: string,
        price: number,
        quantity: number}[]}[],
    reducers: ({
        getMyTables: (state, action: PayloadAction<{tableId:number, tableName:string, invoiceCode:string, data: {key: string,
            name: string,
            price: number,
            quantity: number}[]}[]>) => {
            state = [];
            return action.payload;
        },
    })
})
