import React, {useState, useEffect} from "react";
import { Select, Radio } from "antd";
import CustomTable from "../CustomTable/CustomTable.view";
import styles from './TableOrder.module.css';
import { useSelector } from "react-redux";
import { RootState } from "../../redux/store";
import type { CheckboxGroupProps } from 'antd/es/checkbox';
import { API_BASE_URL } from "../../config";
type TableOrderProps = {
  id:number
}
type TableDataType = {
  tableId: number;
  tableName: string;
  invoiceCode?: string;
  data: {
    key: string;
    name: string;
    price: number;
    quantity: number;
  }[];
};
const TableOrder = (props:TableOrderProps) => {
  const [tableId, setTableId] = useState(0);
  const drinklist = useSelector((state:RootState)=>state.drinkList);
  const myTables = useSelector((state:RootState)=>state.myTables);
  console.log(myTables);
  const optionsRadio: CheckboxGroupProps<string>['options'] = [
    { label: 'Order mới', value: '0' },
    { label: 'Hiện tại', value: '1' },
    { label: 'Trong ngày', value: '2' },
  ];
  useEffect(()=>{   
    if (!props.id) return;
    if(tableId!=0){
        let tableItem = tableData.findIndex(x=>x.tableId == tableId);
        let checkItem = tableData[tableItem].data.findIndex(x=>Number(x.key) == props.id)
    console.log(checkItem);
    if(checkItem==-1){
        let newTableData = [...tableData];
          newTableData[tableItem].data = [...newTableData[tableItem].data, {
            key: props.id.toString(),
            price: drinklist.filter(x=>x.id==props.id)[0].price,
            name: drinklist.filter(x=>x.id==props.id)[0].name,
            quantity: 1
        }];
        setTableData(newTableData);
        setDisplayData(newTableData.filter(x=>x.tableId==tableId));
    }
    else{
        tableData[tableItem].data[checkItem].quantity = tableData[tableItem].data[checkItem].quantity + 1;
        setDisplayData(tableData.filter(x=>x.tableId==tableId));
    }
    
  }},[props]);
    const handleChange = (value: string) => {
        if(value=='0')
            setDisplayData(tableData.filter(x=>x.tableId!=0));
        else{
            setDisplayData(tableData.filter(x=>x.tableId.toString()==value));
        }
        setTableId(Number(value));
      };
    const [tableData, setTableData] = useState<TableDataType[]>([]);   
    const [displayData, setDisplayData] = useState<TableDataType[]>([]);
  const onResponseDelete = (id:string, tableId:number) => {
      let newData = tableData;
      let tableIndex = newData.findIndex(x=>x.tableId == tableId);
      let previous = newData.slice(0, tableIndex);
      let after = newData.slice(tableIndex+1);
      newData[tableIndex].data.splice(newData[tableIndex].data.findIndex(x=>x.key==id), 1);
      setTableData([...previous, newData[tableIndex], ...after]);
      setDisplayData([...previous, newData[tableIndex], ...after].filter(x=>x.tableId==tableId));
  }
  const onResponseChange = (id:string, tableId:number, increase:boolean) => {
    let newData = tableData;
    let tableIndex = newData.findIndex(x=>x.tableId == tableId);
    let previous = newData.slice(0, tableIndex);
    let after = newData.slice(tableIndex+1);
    newData[tableIndex].data[newData[tableIndex].data.findIndex(x=>x.key==id)].quantity = increase?
    newData[tableIndex].data[newData[tableIndex].data.findIndex(x=>x.key==id)].quantity + 1:
    newData[tableIndex].data[newData[tableIndex].data.findIndex(x=>x.key==id)].quantity > 1 ?
    newData[tableIndex].data[newData[tableIndex].data.findIndex(x=>x.key==id)].quantity - 1 :
    newData[tableIndex].data[newData[tableIndex].data.findIndex(x=>x.key==id)].quantity;
    setTableData([...previous, newData[tableIndex], ...after]);
    setDisplayData([...previous, newData[tableIndex], ...after].filter(x=>x.tableId==tableId));
    setTableId(tableId);
}
useEffect(() => {
  if (myTables.length > 0) {
    const cloned = JSON.parse(JSON.stringify(myTables));
    setTableData(cloned);
    setDisplayData(cloned); // hoặc lọc theo tableId nếu muốn
  }
}, [myTables]);
    return(
        <div className={styles.container}>
          <div className={styles.header} style={{backgroundColor:'white'}} >
          <Radio.Group block options={optionsRadio} defaultValue="0" 
          onChange={(e)=>{
            if(e.target.value=='1'){
              fetch(API_BASE_URL+'api/Invoice/' + tableId, {
                method:'GET',
                headers: {
                  'Content-Type':'application/json',
                  'Authorization': `Bearer ${localStorage.getItem('token')??' '}`
                }
              })
              .then(response=>response.json())
              .then((datas:any)=>{
                if(tableId!=0){
                  let tableItem = tableData.findIndex(x=>x.tableId == tableId);
                  tableData[tableItem].invoiceCode = datas.invoiceCode;
                  tableData[tableItem].data = datas.details.map((item:any)=>{
                      return {
                        key: item.drinkId.toString(),
                        price: drinklist.filter(x=>x.id==item.drinkId)[0].price,
                        name: drinklist.filter(x=>x.id==item.drinkId)[0].name,
                        quantity: item.quantity
                    }
                  })
                  let previous = tableData.slice(0,tableItem);
                  let after = tableData.slice(tableItem+1);
                  setTableData([...previous, tableData[tableItem], ...after]);
                  setDisplayData([...previous, tableData[tableItem], ...after].filter(x=>x.tableId==tableId));
                }
              })
              .catch(errors=>console.log(errors))
          }
          else if(e.target.value=='0'){
            if(tableId!=0){
              let tableItem = tableData.findIndex(x=>x.tableId == tableId);
              tableData[tableItem].invoiceCode = 'no';
              tableData[tableItem].data = []
              let previous = tableData.slice(0,tableItem);
              let after = tableData.slice(tableItem+1);
              setTableData([...previous, tableData[tableItem], ...after]);
              setDisplayData([...previous, tableData[tableItem], ...after].filter(x=>x.tableId==tableId));
            }
          }
        
        }}
          />
          </div>          
            <div className={styles.header} >
            Chọn bàn: &nbsp; <Select
      defaultValue="0"
      style={{ width: '80%' }}
      onChange={handleChange}
      options={myTables.map(item=>{
        return {value:item.tableId.toString(), label: item.tableName}
      })}
    />
            </div>
           <div className={styles.content}>
            {displayData.map((item:any)=>{
                return(
                    <CustomTable data={item.data} tableId={item.tableId} invoiceCode={item.invoiceCode}
                    onDelete={onResponseDelete} onChangeQuantity={onResponseChange}
                    />
                )
            })}              
           </div>
        </div>
    )
}
export default TableOrder