import React, {useEffect, useState} from "react";
import { Space, Table, Modal, Form, Input, Button, message, InputNumber } from 'antd';
import type { TableProps } from 'antd';
import {HubConnectionBuilder} from '@microsoft/signalr';
import type { ColumnsType } from 'antd/es/table';
import { API_BASE_URL } from "../../config";
interface DataType {
  branchId: number;
  branchName: string;
  brandAddress: string;
  telephone: string;
}
const columns: TableProps<DataType>['columns'] = [
  {
    title: 'Chi nhánh',
    dataIndex: 'branchId',
    key: 'branchId',
    render: (text) => <a>{text}</a>,
  },
  {
    title: 'Tên chi nhánh',
    dataIndex: 'branchName',
    key: 'branchName',
  },
  {
    title: 'Địa chỉ',
    dataIndex: 'branchAddress',
    key: 'branchAddress',
  },
  {
    title: 'Điện thoại',
    dataIndex: 'telephone',
    key: 'telephone',
  },
  {
    title: 'Action',
    key: 'action',
    render: (_, record) => (
      <Space size="middle">
        <a>Delete</a>
      </Space>
    ),
  },
];

const Branch = () => {
    const [data, setData] = useState<any>([]);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isModaTablelOpen, setIsModalTableOpen] = useState(false);
  const [expandedRowKeys, setExpandedRowKeys] = useState<React.Key[]>([]);
  const [activeBranchId, setActiveBranchId] = useState(0);
  const showModal = () => {
    setIsModalOpen(true);
  };

  const handleOk = () => {
    setIsModalOpen(false);
  };
  const onExpand = (expanded: boolean, record:any) => {
    console.log(record.branchId);
    console.log(expanded);
    setExpandedRowKeys(expanded ? [record.branchId] : []);
  }
  const handleCancel = () => {
    setIsModalOpen(false);
  };
    const expandedRowRender = (record:any) => {
      let subData = data.filter((x:any)=>x.branchId == record.branchId)[0].tables;
      const columns: ColumnsType<any> = [
        { title: 'Stt', dataIndex: 'tableNumber', key: 'tableNumber',
        },
        { title: 'Tên bàn', dataIndex: 'tableName', key: 'tableName'},
        { title: 'Vị trí', dataIndex: 'position', key: 'position'}
      ];
      return (
        <div>
            <a><img src='images/add.png' style={{width:'30px', height:'30px'}} 
            onClick={()=>{
              setActiveBranchId(record.branchId);
              setIsModalTableOpen(true);
            }}
            /></a>
            <Table columns={columns} dataSource={subData} />
      </div>
      )
    }
    const token = localStorage.getItem('token')??' ';
    const onFinishTable = (values:any) => {
        if(activeBranchId!=0){
            fetch(API_BASE_URL+'api/MyTable', {
              method:'POST',
              headers: {
                'Content-Type':'application/json',
                'Authorization': `Bearer ${token}`
              },
              body: JSON.stringify({tableName: values.tableName,
                position: values.position, branchId: activeBranchId
              })
            }).then(response=>response.json())
            .then(data=>{
              if(data.message=="Added"){
                  getData();
                  setIsModalTableOpen(false);
              }
            })
            .catch(error=>console.log(error));
        }
    }
    const onFinish = (values:any) => {
  console.log('Success:', values);
  fetch(API_BASE_URL + 'api/Branch', {
                method:'POST',
                headers: {
                    'Content-Type':'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({
                    branchId: values.branchId,
                    branchName:values.branchName,
                    branchAddress: values.branchAddress,
                    telephone: values.telephone
                })
            }).then(response => response.json())
.then(data => {
    if (data.message === "Added") {
        getData();
        setIsModalOpen(false);
    } else {
        message.info(data.message);
    }
})
.catch(error => console.error("Fetch error:", error.message));
};
const getData = ()=>{
    fetch(API_BASE_URL + 'api/Branch', {
                method:'GET',
                headers: {
                    'Content-Type':'application/json'
                }
            }).then(response=>response.json())
            .then(data=>setData(data))
            .catch(errors=>console.log(errors))
}
const onFinishFailed = (errorInfo: any) => {
  console.log('Failed:', errorInfo);
};
        useEffect(()=>{
          const connection = new HubConnectionBuilder()
              .withUrl(API_BASE_URL + "notificationHub")
              .build();
          
          connection.on("ReceiveLatestBranch", function (message:string) {
              console.log("Received:", message);
              getData();
          });
          connection.start().catch(err => console.error(err));
          getData();
        },[])
    return(
        <div style={{height:'75vh', overflowY:'scroll'}}>
            <h1>Quản lý các chi nhánh <a onClick={showModal}><img src='images/add.png' style={{width:'30px', height:'30px'}} /></a></h1>
            <Table<DataType> rowKey="branchId" columns={columns} dataSource={data} expandable={{ expandedRowRender, expandedRowKeys, onExpand, }}/>
            <Modal
        title="Thêm chi nhánh mới"
        closable={{ 'aria-label': 'Custom Close Button' }}
        open={isModalOpen}
        onOk={handleOk}
        onCancel={handleCancel} footer={null}
      >
        <Form
    name="basic"
    labelCol={{ span: 8 }}
    wrapperCol={{ span: 16 }}
    style={{ maxWidth: 600 }}
    initialValues={{ remember: true }}
    onFinish={onFinish}
    onFinishFailed={onFinishFailed}
    autoComplete="off"
  >
    <Form.Item
      label="Chi nhánh số"
      name="branchId"
      rules={[{ required: true, message: 'Please input your branch id!' }]}
    >
      <InputNumber
                min={1}
                max={10000}
                placeholder="Enter a number"
                style={{ marginRight: 10 }}
        />
    </Form.Item>
    <Form.Item
      label="Tên chi nhánh"
      name="branchName"
      rules={[{ required: true, message: 'Please input your branch name!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item
      label="Địa chỉ chi nhánh"
      name="branchAddress"
      rules={[{ required: true, message: 'Please input your branch address!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item
      label="Điện thoại chi nhánh"
      name="telephone"
      //rules={[{ required: true, message: 'Please input your branch address!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item label={null}>
      <Button type="primary" htmlType="submit">
        Lưu dữ liệu
      </Button>
    </Form.Item>
  </Form>
      </Modal>
      <Modal
        title="Thêm bàn mới"
        closable={{ 'aria-label': 'Custom Close Button' }}
        open={isModaTablelOpen}
        footer={null}
      >
        <Form
    name="basic"
    labelCol={{ span: 8 }}
    wrapperCol={{ span: 16 }}
    style={{ maxWidth: 600 }}
    initialValues={{ remember: true }}
    onFinish={onFinishTable}
    onFinishFailed={onFinishFailed}
    autoComplete="off"
  >
    <Form.Item
      label="Tên bàn"
      name="tableName"
      rules={[{ required: true, message: 'Please input your branch name!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item
      label="Vị trí"
      name="position"
      rules={[{ required: true, message: 'Please input table position!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item label={null}>
      <Button type="primary" htmlType="submit">
        Lưu dữ liệu
      </Button>
    </Form.Item>
  </Form>
      </Modal>
        </div>
    )
}
export default Branch;