export function toCustomISOStringWithOffset(date = new Date()) {
    const pad = (num:any) => String(num).padStart(2, '0');
    const year = date.getFullYear();
    const month = pad(date.getMonth() + 1);
    const day = pad(date.getDate());
    const hours = pad(date.getHours());
    const minutes = pad(date.getMinutes());
    const seconds = pad(date.getSeconds());
    const ms = String(date.getMilliseconds()).padStart(3, '0');
    // Get timezone offset in minutes
    const offsetMinutes = -date.getTimezoneOffset();
    const offsetSign = offsetMinutes >= 0 ? '+' : '-';
    const offsetHour = pad(Math.floor(Math.abs(offsetMinutes) / 60));
    const offsetMin = pad(Math.abs(offsetMinutes) % 60);
    return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}.${ms}${offsetSign}${offsetHour}:${offsetMin}`;
}
console.log(toCustomISOStringWithOffset());
