import React, {useEffect, useState} from "react";
import style from './DrinkList.module.css';
import Drink from "../Drink/Drink.view";
import { getDataFromAPI } from "../libraries/getDataFromAPI";
import {HubConnectionBuilder} from '@microsoft/signalr';
import { chunkArray } from "../libraries/arrayProcess";
import { RootState } from "../../redux/store";
import { useDispatch, useSelector } from 'react-redux';
import { UseDispatch } from "react-redux";
import { drinklistSlice } from "../../redux/drinkListReducer";
import { API_BASE_URL } from "../../config";
type DrinkListProps = {
    onOrdering: (id:number)=>void
}
const DrinkList = (props:DrinkListProps) => {
    const [totalRows, setTotalRows] = useState(0);
    const drinklist = useSelector((state:RootState)=>state.drinkList);
    const dispatch = useDispatch();
    const onReceiveOrderId = (id:number)=>{
        props.onOrdering(id);
    }
    console.log('I re rendered!!!!');
    async function getData(){
        let data = await getDataFromAPI(API_BASE_URL+'api/Drink', localStorage.getItem('token')??' ');
        if(data!='Disconnect'){
            return new Promise(resolve=>{
              dispatch(drinklistSlice.actions.getDrinkList(data.map((item:any)=>{
                return {
                    id: item.drinkId,
                    name: item.drinkName,
                    price: item.price,
                    imageUrl: item.imageUrl
                }
            })))
                resolve(data.length);
            })               
        }
      }
    useEffect(()=>{
        getData().then((data:any)=>setTotalRows(Math.ceil(data/3)));
    },[])
    return(
        <div className={style.container}>
            {totalRows==0?<h2>Loading...</h2>:<div>
            {chunkArray(drinklist, 3).map((row:any, rowIndex:number)=>{
                return(
                    <div className={style.row} key={rowIndex}>
                        {row.map((item:any)=>{
                            return(
                                <Drink imageUrl={item.imageUrl} drinkName={item.name} 
                            price={item.price} onOrdering={onReceiveOrderId}
                            id={item.id} key={item.id}
                            />
                            )
                        })}
                    </div>
                )
            })}        
        </div>}
        </div>
    )
}
export default React.memo(DrinkList);