import React, { useState, useEffect, lazy } from 'react';
import { Breadcrumb, Layout, Menu, theme } from 'antd';
import Transaction from '../transaction/Transaction.view';
import CustomLine from '../../components/charts/LineChart/CustomLine.view';
import { getDataFromAPI } from "../../components/libraries/getDataFromAPI";
import { useDispatch } from "react-redux";
import { myTablesSlice } from '../../redux/myTableReducer';
import Branch from '../../components/branch/Branch.view';
import Staff from '../../components/staff/Staff.view';
import Test1405 from '../../components/test1405/Test1405.view';
import { stopSignalRConnection } from '../../components/libraries/signalRConnection';
//import { useSignalR } from '../../components/libraries/SignalRContext';
//import { useSetSignalR } from '../../components/libraries/SignalRContext';
import { getSignalRConnection } from '../../components/libraries/signalRConnection';
import './style.css';
import { API_BASE_URL } from '../../config';
const { Header, Content, Footer } = Layout;
const items = [
    {
        key: '1',
        label: 'Giao dịch'
    },
    {
        key: '2',
        label: 'Thống kê'
    },
    {
        key:'4',
        label:'Chi nhánh'
    },
    {
      key:'5',
      label:'Nhân viên'
  },
  {
      key:'6',
      label:'Danh mục món'
  },
    {
        key: '3',
        label: 'Đăng xuất'
    }
];

const Dashboard: React.FC = () => {
  const [indexSelected, setIndexSelected] = useState(1);
  const connection = getSignalRConnection();
  const {
    token: { colorBgContainer, borderRadiusLG },
  } = theme.useToken();
  const dispatch = useDispatch();
  async function getData(){
    let data = await getDataFromAPI(API_BASE_URL+'api/MyTable?id='+localStorage.getItem('branchId'),
                      localStorage.getItem('token')??' ');
    if(data!='Disconnect'){
        return new Promise(resolve=>{
          let myData = [{tableId: 0,
            tableName: 'Tất cả', invoiceCode:'no',
            data: []}];
            data.map((item:any)=>{
              myData.push({
                tableId: item.tableNumber,
                tableName: item.tableName,
                invoiceCode:'no',
                data: []
              })
          })
          dispatch(myTablesSlice.actions.getMyTables(myData))
            resolve(myData.length);
        })               
    }
  }
  const logout = async () => {
  await stopSignalRConnection(); // Stops the hub connection
};
useEffect(()=>{
    getData();
},[])
  useEffect(()=>{
      console.log(connection);
      if(!connection) return;
      connection.on("sendLogoutRequest", async (msg:string)=>{
        alert("hello: " + msg);
          if(msg=='logout'){
              await logout();
              localStorage.clear();
              window.location.reload();
          }
      })
  },[])
  return (
    <Layout style={{height:'100vh'}}>
      <Header
        style={{
          position: 'sticky',
          top: 0,
          backgroundColor:'#ffffff',
          zIndex: 1,
          width: '100%',
          display: 'flex',
          alignItems: 'center'
        }}
      >
        <div className="demo-logo" />
        <Menu
          className='custom-menu'
          mode="horizontal"
          defaultSelectedKeys={['1']}
          items={items}
          style={{ flex: 1, minWidth: 0, backgroundColor:'darkgreen', fontSize:18,
            paddingLeft:'10px', fontWeight:600 }}
          onClick={async (info:any)=>{
            switch(info.key){
              case '3':
                await logout();
                localStorage.clear();
                window.location.reload();
                break;
              case '2':
                setIndexSelected(2);
                break;
              case '4':
                  setIndexSelected(4);
                  break;
                  case '5':
                    setIndexSelected(5);
                    break;
              case '6':
                    setIndexSelected(6);
                    break;
              default:
                setIndexSelected(1);
            }
          }}
        />
        <p style={{backgroundColor:'darkgreen', paddingRight:'40px', fontSize:20, color:'#ffffff'
        }}>Nhân viên: {localStorage.getItem('username')}</p>
      </Header>
      <Content style={{ padding: '0 48px' }}>
        <div
          style={{
            padding: 24,
            minHeight: 380,
            background: colorBgContainer,
            borderRadius: borderRadiusLG,
          }}
        >
          {indexSelected==1?<Transaction />:indexSelected==2?<CustomLine />
          :indexSelected==4?<Branch />:indexSelected==6?<Test1405 />:<Staff />}
        </div>
      </Content>
      <Footer style={{ textAlign: 'center', paddingRight:'50px', paddingTop:'0px', marginTop:'0px' }}>
         <p style={{backgroundColor:'darkgreen', fontSize:'20px', padding:'20px 0px'}}>Created by Nvcmis - 04/2025</p>
      </Footer>
    </Layout>
  );
};

export default Dashboard;