import React, { useState } from 'react';
import { Space, Table, Upload, Modal, Button, Form, Input, InputNumber, message } from 'antd';
import type { TableProps } from 'antd';
import { RootState } from "../../redux/store";
import { drinklistSlice } from '../../redux/drinkListReducer';
import { getDataFromAPI } from '../libraries/getDataFromAPI';
import { UploadOutlined } from '@ant-design/icons';
import { useDispatch, useSelector } from 'react-redux';
import './style.css';
import { isEditable } from '@testing-library/user-event/dist/utils';
import { API_BASE_URL } from '../../config';
interface DataType {
  id: number;
  name: string;
  price: number;
  imageUrl: string;
  isEditable:boolean;
}
const Test1405: React.FC = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isModalImageOpen, setIsModalImageOpen] = useState(false);
    const dispatch = useDispatch();
    const drinklist = useSelector((state:RootState)=>state.drinkList);
    const [data, setData] = useState<DataType[]>(drinklist);
    const [activePrice, setActivePrice] = useState(0);
    const [activeId, setActiveId] = useState(0);
    const columns: TableProps<DataType>['columns'] = [
  {
    title: 'id',
    dataIndex: 'id',
    key: 'id',
    hidden:true
  },
  {
    title: 'Hình',
    dataIndex: 'imageUrl',
    key: 'imageUrl',
    render: (_:string, record:DataType, index:number)=>{
      return(
        <img src={record.imageUrl} style={{width:'50px', height:'50px'}} 
        onClick={()=>{setIsModalImageOpen(true); setActiveId(record.id)}}
        />)
    }
  },
  {
    title: 'Tên món',
    dataIndex: 'name',
    key: 'name',
  },
  {
    title: 'Đơn giá',
    dataIndex: 'price',
    key: 'price',
    render:(text:string, record:DataType, index:number) => {
      return !record.isEditable ? (
        <a onClick={()=>{
          setActivePrice(record.price);
          let index = drinklist.findIndex(x=>x.id==record.id);
          let newData:DataType[] = [];
          if(index!=-1){
              let previous = drinklist.slice(0, index);
              let after = drinklist.slice(index+1);
              newData = [...previous, {...drinklist[index], isEditable: true}, ...after];
          }
          else
              newData = drinklist;
          dispatch(drinklistSlice.actions.getDrinkList(
              newData
          ))
        }}>{record.price}</a>
      ) : <InputNumber value={activePrice} onChange={(value)=>{
        setActivePrice(value!=null?value:0);
      }} onKeyDown={(e)=>{
        if(e.key=='Enter'){
            //Call API to update data
            // Update redux store
            updateDrink(record.id, undefined, undefined, activePrice);
        }
      }}
      />
    }
  },
  {
    title: 'Action',
    key: 'action',
    render: (_, record) => (
      <Space size="middle">
        <a>Delete</a>
      </Space>
    ),
  },
];

    const handleOk = () =>{
        setIsModalOpen(false);
    }
    const handleCancel = () => {
        setIsModalOpen(false);
    }
    const showModal = ()=> {
        setIsModalOpen(true);
    }
    async function updateDrink(id:number, image?:File, drinkName?:string, price?:number){
        const formData = new FormData();
        if(drinkName!=null&&drinkName!=undefined)
            formData.append('drinkName', drinkName);
        if(price!=null&&price!=0)
            formData.append('price', price.toString());
        if (image!=null&&image!=undefined) {
            formData.append('drinkImage', image);
    }
    fetch(API_BASE_URL+'api/Drink/' + id, {
  method: 'PUT',
  headers: {
    'Authorization':`Bearer ${localStorage.getItem('token')??' '}`
  },
  body: formData
})
  .then(response => response.json())
  .then(async (data:any) => {
    if(data.message=='Updated'){
          let index = drinklist.findIndex(x=>x.id==id);
          let newData:DataType[] = [];
          if(index!=-1){
              let previous = drinklist.slice(0, index);
              let after = drinklist.slice(index+1);
              if(price!=null||undefined)
                newData = [...previous, {...drinklist[index], isEditable: false, price:activePrice}, ...after];
              if(image!=null){
                const imageUrl = URL.createObjectURL(image); 
                newData = [...previous, {...drinklist[index], imageUrl:imageUrl}, ...after];
              }
          }
          else
              newData = drinklist;
          dispatch(drinklistSlice.actions.getDrinkList(
              newData
          ))
    }
  })
  .catch(error => console.error(error));
    }
    async function getData(){
            let data = await getDataFromAPI(API_BASE_URL+'api/Drink', localStorage.getItem('token')??' ');
            if(data!='Disconnect'){
                return new Promise(resolve=>{
                  dispatch(drinklistSlice.actions.getDrinkList(data.map((item:any)=>{
                    return {
                        id: item.drinkId,
                        name: item.drinkName,
                        price: item.price,
                        imageUrl: item.imageUrl,
                        isEditable:false
                    }
                })))
                    resolve(data.length);
                })               
            }
          }
    const onFinish = (values:any) => {
        const formData = new FormData();
    formData.append('drinkName', values.drinkName);
    formData.append('price', values.price);
    if (values.upload && values.upload.length > 0) {
      formData.append('drinkImage', values.upload[0].originFileObj);
    }
    fetch(API_BASE_URL+'api/Drink', {
  method: 'POST',
  headers: {
    'Authorization':`Bearer ${localStorage.getItem('token')??' '}`
  },
  body: formData
})
  .then(response => response.json())
  .then(async (data:any) => {
    console.log(data);
    await getData();
    message.success("Một món mới đã được thêm vào hệ thống!!!");
    setIsModalOpen(false);
  })
  .catch(error => console.error(error));
    }
  const onFinishUpdateImage = async (values:any) => {
    if (values.upload && values.upload.length > 0) {
      await updateDrink(activeId, values.upload[0].originFileObj);
      setIsModalImageOpen(false);
    }
  }
    return(
     <div style={{height:'75vh', overflowY:'scroll'}}>
        <Button onClick={showModal}>Thêm mới</Button>
        <Table<DataType> columns={columns} dataSource={drinklist} 
className='my-custom-table' rowClassName={(record:DataType, index:number)=>index%2==0?'even-row':'odd-row'}
/>
<Modal
        title="Thêm món mới"
        closable={{ 'aria-label': 'Custom Close Button' }}
        open={isModalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
      >
       <Form
    name="basic"
    labelCol={{ span: 8 }}
    wrapperCol={{ span: 16 }}
    style={{ maxWidth: 600 }}
    initialValues={{ remember: true }}
    onFinish={onFinish}
    autoComplete="off"
  >
    <Form.Item
      label="Tên món"
      name="drinkName"
      rules={[{ required: true, message: 'Please input your drink name!' }]}
    >
      <Input />
    </Form.Item>
    <Form.Item
      label="Đơn giá"
      name="price"
      rules={[{ required: true, message: 'Please input price!' }]}
    >
      <InputNumber />
    </Form.Item>
    <Form.Item
  name="upload"
  label="Upload"
  valuePropName="fileList"
  getValueFromEvent={e => Array.isArray(e) ? e : e && e.fileList}
>
  <Upload beforeUpload={() => false}>
    <Button icon={<UploadOutlined />}>Select File</Button>
  </Upload>
</Form.Item>
    <Form.Item label={null}>
      <Button type="primary" htmlType="submit">
        Submit
      </Button>
    </Form.Item>
  </Form>
      </Modal>
<Modal
        title="Cập nhật ảnh cho món"
        closable={{ 'aria-label': 'Custom Close Button' }}
        open={isModalImageOpen}
        footer={null}
        onCancel={()=>setIsModalImageOpen(false)}
      >
       <Form
    name="basic"
    labelCol={{ span: 8 }}
    wrapperCol={{ span: 16 }}
    style={{ maxWidth: 600 }}
    initialValues={{ remember: true }}
    onFinish={onFinishUpdateImage}
    autoComplete="off"
  >
    <Form.Item
  name="upload"
  label="Upload"
  valuePropName="fileList"
  getValueFromEvent={e => Array.isArray(e) ? e : e && e.fileList}
>
  <Upload beforeUpload={() => false}>
    <Button icon={<UploadOutlined />}>Select File</Button>
  </Upload>
</Form.Item>
    <Form.Item label={null}>
      <Button type="primary" htmlType="submit">
        Lưu dữ liệu
      </Button>
    </Form.Item>
  </Form>
      </Modal>

</div>)
}
export default Test1405;