import React from 'react';
import { Card } from 'antd';
import styles from './Drink.module.css';
const { Meta } = Card;
type DrinkProps = {
    id: number,
    imageUrl: string,
    drinkName: string,
    price:number,
    onOrdering: (id:number)=>void
}
const Drink = (props:DrinkProps) => (
  <Card
    hoverable
    style={{ width: 240 }}
    cover={<img alt="example" src={props.imageUrl} 
    onClick={()=>{
      localStorage.getItem('editable') != 'no' ?
      props.onOrdering(props.id) : alert('Không được phép thay đổi dữ liệu');
    }}
    />}
  >
    <div className={styles.priceBadge}>{props.price.toLocaleString()}</div>
    <Meta title={props.drinkName} />
  </Card>
);

export default Drink;