import React, {useEffect, useState} from 'react';
import { Button, Input, Form, Select, message } from 'antd';
import { UserOutlined, LockOutlined, MailOutlined, FacebookOutlined, GoogleOutlined } from '@ant-design/icons';
import { useTranslation } from 'react-i18next';
import { createSignalRConnection } from '../libraries/signalRConnection';
import { useNavigate } from 'react-router-dom';
import styles from './LoginForm.module.css';
import { API_BASE_URL } from '../../config';

const LoginForm = (props: { setToken: any }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [branchOptions, setBranchOptions] = useState([{value:'1', label:'Chi nhánh 1 - Lạc Long Quân'},
    {value:'2', label:'Chi nhánh 2 - Bình Thới'}, {value:'3', label:'Chi nhánh 3 - Thái Phiên'}
  ])
  const [errorMessage, setErrorMessage] = useState('');
  useEffect(()=>{
      fetch(API_BASE_URL+'api/Branch')
      .then(response=>response.json())
      .then(data=>{
        setBranchOptions(data.map((item:any)=>{
          return {value:item.branchId.toString(), label:item.branchName}
        }))
      })
  },[])
  //const setSignalR = useSetSignalR();
  const onFinish = async (values: any) => {
    fetch(API_BASE_URL+'api/Authentication', {
      method:'POST',
      headers: {
        'Content-Type':'application/json'
      },
      body: JSON.stringify({
        userName: values.username,
        password: values.password
      })
    }).then(response=>response.json())
    .then(async(data:any)=>{
      if(data.message!="Invalid username or password"){
          localStorage.setItem('username', values.username);
          localStorage.setItem('token', data.message);
          //const conn = await createSignalRConnection(data.message);
    try {
      //await conn.start();
      props.setToken(data.message);
      navigate('/dashboard');
      console.log("SignalR started");
    } catch (err) {
      console.error("SignalR start failed", err);
    }         
      }
})
    .then(errors=>console.log(errors));
  };
  return (
    <div className={styles.loginContainer}>
      <div className={styles.loginBox}>
        <h2>{t('signIn')}</h2>
        <Form onFinish={onFinish}>
          <Form.Item name="branchId" rules={[{ required: true, message: t('branch required') }]}>
            <Select options={branchOptions} onChange={(value:string)=>localStorage.setItem('branchId', value)}/>
          </Form.Item>
          <Form.Item name="username" rules={[{ required: true, message: t('usernameRequired') }]}>
            <Input prefix={<UserOutlined />} placeholder={t('username')} />
          </Form.Item>
          <Form.Item name="password" rules={[{ required: true, message: t('passwordRequired') }]}>
            <Input.Password prefix={<LockOutlined />} placeholder={t('password')} />
          </Form.Item>
          <Form.Item>
            <Button type="primary" htmlType="submit" block className={styles.loginButton}>
              {t('enter')}
            </Button>
          </Form.Item>
        </Form>
        <div className={styles.alternativeSignin}>
          <p>{t('orSignInWith')}</p>
          <div className={styles.iconGroup}>
            <MailOutlined />
            <FacebookOutlined />
            <GoogleOutlined />
          </div>
          <p style={{color:'red'}}>{errorMessage}</p>
        </div>
        <p className={styles.registerText}>
          {t('noAccount')} <a href="/register">{t('register')}</a>
        </p>
      </div>
    </div>
  );
};

export default LoginForm;
