import React, {useState, useEffect} from "react";
import TableOrder from "../../components/TableOrder/TableOrder.view";
import { useCallback } from "react";
import DrinkList from '../../components/DrinkList/DrinkList.view';
import { getDataFromAPI } from "../../components/libraries/getDataFromAPI";
import { useDispatch } from "react-redux";
import { drinklistSlice } from "../../redux/drinkListReducer";
import styles from './Transaction.module.css';
import { API_BASE_URL } from "../../config";
const Transaction = () => {
  const [data, setData] = useState<{id:number, isRendered:boolean}>({id:0, isRendered:false});
  const onReceiveOrder = useCallback((id:number)=>{
      setData({id:id, isRendered:!data.isRendered});
  },[]);
  const dispatch = useDispatch();
  async function getData(){
    let data = await getDataFromAPI(API_BASE_URL + 'api/Drink',
      localStorage.getItem('token')??' '
    );
    console.log(data);
    if(data!='Disconnect'){
        return new Promise(resolve=>{
          dispatch(drinklistSlice.actions.getDrinkList(data.map((item:any)=>{
            return {
                id: item.drinkId,
                name: item.drinkName,
                price: item.price,
                imageUrl: item.imageUrl
            }
        })))
            resolve(data.length);
        })               
    }
  }
  useEffect(()=>{
      getData();
  },[])
    return(
    <div className={styles.container}>
      <TableOrder id={data.id} />
      <DrinkList onOrdering={onReceiveOrder} />
    </div>
    )
}
export default Transaction;