import { useEffect, useState } from 'react';
import { LineChart, PieChart, Pie, ResponsiveContainer, Cell, Line, 
  Tooltip, CartesianGrid, XAxis, YAxis, BarChart, Bar } from 'recharts';
import { getDataFromAPI } from '../../libraries/getDataFromAPI'; 
import { Button, DatePicker, Radio } from 'antd';
import dayjs from 'dayjs';
import type { CheckboxGroupProps } from 'antd/es/checkbox';
import { API_BASE_URL } from '../../../config';
const { RangePicker } = DatePicker;
const optionsRadio: CheckboxGroupProps<string>['options'] = [
    { label: 'Thống kê theo loại nước uống', value: '0' },
    { label: 'Thống kê doanh số theo chi nhánh', value: '1' },
  ];
const CustomLine = ()=>{
  const [salesData, setSalesData] = useState<{name: string, value:number}[]>([]);
  const [dateRange, setDateRange] = useState<[dayjs.Dayjs, dayjs.Dayjs]>([
    dayjs().startOf('day'),
    dayjs().endOf('day'),
  ]);
  const [currentOption, setCurrentOption] = useState('0');
  async function getData(url:string){
    const [startDay, endDay] = dateRange;
    // Set from 00:00:00
    const from = startDay.startOf('day').toDate().toISOString();
    // Set to 23:59:59.999
    const to = endDay.endOf('day').toDate().toISOString();
    let data = await getDataFromAPI(url + 'from=' + from + '&to=' + to, localStorage.getItem('token')??'');
    setSalesData(data.filter((x:any)=>x.name!=null).map((item:any)=>{
      return(
        {
            name: item.name,
            value: item.value
        }
      )
    }))
  }
  useEffect(()=>{
      getData(API_BASE_URL+'api/Statistic?');
  },[]);
    // const salesData = [
    //     { name: 'January', value: 10000 },
    //     { name: 'February', value: 12000 },
    //     { name: 'March', value: 8000 },
    //     { name: 'April', value: 15000 },
    //     { name: 'May', value: 10000 },
    //     { name: 'June', value: 11000 },
    //     { name: 'July', value: 12000 },
    //     { name: 'August', value: 9000 },
    //     { name: 'September', value: 12000 },
    //     { name: 'October', value: 12000 },
    //     { name: 'November', value: 13000 },
    //     { name: 'December', value: 7500 }
    //   ];
    const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#0088FE', '#00C49F', '#FFBB28', '#FF8042'];
    
    return(
    <div style={{height:'75vh', overflowY:'scroll'}}>
      <div style={{display:'flex', flexDirection:'row', padding:'20px 0px', marginBottom:'20px',
        justifyContent:'space-evenly', border:'2px solid gray'}}>
      <Radio.Group block options={optionsRadio} defaultValue="0" 
      onChange={(e)=>setCurrentOption(e.target.value)}
      />
      <RangePicker onChange={(dates:any) => setDateRange(dates)} defaultValue={dateRange}/>
        <Button type='primary' onClick={()=>getData(currentOption=='0'?API_BASE_URL + 'api/Statistic?'
          : API_BASE_URL+'api/Statistic/revenue?'
        )}>Thống kê</Button>
      </div>
      <div style={{display:'flex', flexDirection:'row', justifyContent:'space-evenly'}}>
        <div style={{width:'40%', height:'500px'}}>
          <ResponsiveContainer>
          <BarChart data={salesData}>
  <XAxis dataKey="name" />
  <CartesianGrid stroke="#ccc" />
  <YAxis />
  <Tooltip />
  {/* <Line type="monotone" dataKey="value" stroke="#8884d8" /> */}
  <Bar dataKey="value">
  {salesData.map((entry, index) => (
            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
  ))}
  </Bar>
</BarChart>
          </ResponsiveContainer>       
        </div>
      <div style={{width:'40%', height:'500px'}}>
      <ResponsiveContainer>
      <PieChart>
      <Pie
          data={salesData}
          cx="50%"
          cy="50%"
          labelLine={false}
          outerRadius={150}
          fill="#8884d8"
          dataKey="value"
          label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
        >
          {salesData.map((entry, index) => (
            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
          ))}
        </Pie>
      </PieChart>
      </ResponsiveContainer>     
      </div>     
      </div>
  </div>
    )
}
export default CustomLine;