import {createSlice, PayloadAction} from '@reduxjs/toolkit';
import { isEditable } from '@testing-library/user-event/dist/utils';
export const drinklistSlice = createSlice({
    name:'drinklist',
    initialState:[] as {imageUrl:string, name:string, id:number, price:number, isEditable:boolean}[],
    reducers: ({
        getDrinkList: (state, action: PayloadAction<{imageUrl:string, name:string, id:number,
             price:number, isEditable:boolean}[]>) => {
            state = [];
            return action.payload;
        }
    })
})
